 orders:{title:'Sale (POS & Website)',sub:'Manage in-person POS sales and website orders in one sales module.',stats:['Orders today','Awaiting dispatch','Returns & refunds'],features:[['Order management','Order search, status timeline, fulfilment assignment and cancellation rules.'],['Payments & refunds','Payment status, settlement reconciliation, refund approvals and audit trail.'],['Returns & customer care','Return requests, return reasons, replacements and refund tracking.'],['Promotions','Coupon rules, discounts, bundles and campaign performance.']]},
